hints:
```
build 3×3 board: even-indexed moves → A(1), odd-indexed → B(2)
for each of 8 lines (3 rows, 3 cols, 2 diagonals):
    if all three cells are equal and non-zero:
        return winner (A if 1, B if 2)
if move count == 9:
    return "Draw"
return "Pending"
```

code.cpp:
class Solution {
public:
    string tictactoe(vector<vector<int>>& moves) {
        int b[3][3] = {};
        for (int i = 0; i < (int)moves.size(); i++) {
            b[moves[i][0]][moves[i][1]] = (i % 2 == 0) ? 1 : 2;
        }

        for (int i = 0; i < 3; i++) {
            if (b[i][0] && b[i][0] == b[i][1] && b[i][1] == b[i][2])
                return b[i][0] == 1 ? "A" : "B";
            if (b[0][i] && b[0][i] == b[1][i] && b[1][i] == b[2][i])
                return b[0][i] == 1 ? "A" : "B";
        }
        if (b[0][0] && b[0][0] == b[1][1] && b[1][1] == b[2][2])
            return b[0][0] == 1 ? "A" : "B";
        if (b[0][2] && b[0][2] == b[1][1] && b[1][1] == b[2][0])
            return b[0][2] == 1 ? "A" : "B";

        return (moves.size() == 9) ? "Draw" : "Pending";
    }
};
